// Dependency-free %g with precision 6 for f32 (matches C++ default ostream<<float)
pub fn fmt_g6(v: f32) -> String {
    const P: i32 = 6;
    if v.is_nan() {
        return if v.is_sign_negative() { "-nan".into() } else { "nan".into() };
    }
    if v.is_infinite() {
        return if v < 0.0 { "-inf".into() } else { "inf".into() };
    }
    // Correctly-rounded scientific with P significant digits (P-1 fractional).
    let sci = format!("{:.*e}", (P - 1) as usize, v);
    let epos = sci.find('e').unwrap();
    let mant = &sci[..epos];
    let x: i32 = sci[epos + 1..].parse().unwrap();

    if x < -4 || x >= P {
        let m = strip(mant);
        let (sign, ax) = if x < 0 { ('-', -x) } else { ('+', x) };
        format!("{}e{}{:02}", m, sign, ax)
    } else {
        let dec = (P - 1 - x) as usize; // 0..=9
        strip(&format!("{:.*}", dec, v))
    }
}

fn strip(s: &str) -> String {
    if !s.contains('.') { return s.to_string(); }
    let t = s.trim_end_matches('0');
    let t = t.strip_suffix('.').unwrap_or(t);
    t.to_string()
}

fn main() {
    use std::io::{self, Read, Write};
    let mut inp = String::new();
    io::stdin().read_to_string(&mut inp).unwrap();
    let so = io::stdout();
    let mut o = io::BufWriter::new(so.lock());
    for line in inp.lines() {
        let line = line.trim();
        if line.is_empty() { continue; }
        let u = u32::from_str_radix(line, 16).unwrap();
        writeln!(o, "{}", fmt_g6(f32::from_bits(u))).unwrap();
    }
}
EOF
