    int k=snprintf(buf,sizeof buf,"%g\n",(double)f);
    if(o+k>sizeof out){fwrite(out,1,o,stdout);o=0;}
    memcpy(out+o,buf,k); o+=k;
  }
  fwrite(out,1,o,stdout);
  return 0;
}
