include!("/tmp/w/rs/glib.rs");
fn main(){
  // find f32 x (as a short decimal string) with 0.0722f32*x landing on specific targets near 1e-4
  let lo = 9.999995e-5f64; let hi = 1e-4f64;
  // scan f32 values near 1.385e-3
  let mut found: Vec<(String,f32,String)> = vec![];
  let base = (1.3849e-3f32).to_bits();
  for d in 0..200000u32 {
    let x = f32::from_bits(base + d);
    let p = 0.0722f32 * x;
    let pd = p as f64;
    if pd >= lo && pd < hi {
      // x as shortest decimal that round-trips
      let s = format!("{:e}", x);
      if s.parse::<f32>().unwrap() == x { found.push((s, p, fmt_g6(p))); }
      if found.len() > 3 { break; }
    }
  }
  println!("--- v in [9.999995e-5, 1e-4) : rounds UP to 1.00000e-4, exp becomes -4 -> expect FIXED");
  for (s,p,f) in &found { println!("  arg b={}  -> value {:e} (bits {:08x}) mine={}", s, p, p.to_bits(), f); }
  // just below
  let mut found2: Vec<(String,f32,String)> = vec![];
  for d in 0..200000u32 {
    let x = f32::from_bits(base + d);
    let p = 0.0722f32 * x;
